from __future__ import annotations

from typing import Any, Dict, List, Optional

import ctypes
from ctypes import POINTER, byref
from ctypes.wintypes import BOOL, DWORD, HWND, LPARAM

# Type aliases for COM interface pointers.
# These are dynamically generated by comtypes at runtime.
IAccessiblePtr = Any
IAccessible2Ptr = Any
IAccessibleHyperlinkPtr = Any

import comtypes.client
from comtypes import COMError, IServiceProvider

from .api_wrapper import ApiWrapper
from ia2 import (  # type: ignore[attr-defined]
    IAccessible2_2,
    IAccessibleEditableText,
    IAccessibleHyperlink,
    IAccessibleImage,
    IAccessibleTable2,
    IAccessibleTableCell,
    IAccessibleText,
    IAccessibleValue,
    Relation,
    Role,
    msaa_state_list_to_string,
    state_list_to_string,
)

CHILDID_SELF = 0
OBJID_CLIENT = -4
SELFLAG_NONE = 0
E_NOTIMPL = -2147467263  # 0x80004001 as a signed HRESULT

user32 = ctypes.windll.user32  # type: ignore
oleacc = ctypes.oledll.oleacc  # type: ignore
oleacc_mod = comtypes.client.GetModule("oleacc.dll")
IAccessible = oleacc_mod.IAccessible  # noqa: N816


def accessible_object_from_window(hwnd: HWND) -> IAccessiblePtr:
    p = POINTER(IAccessible)()
    oleacc.AccessibleObjectFromWindow(
        hwnd, OBJID_CLIENT, byref(IAccessible._iid_), byref(p)
    )
    return p


def name_from_hwnd(hwnd: HWND) -> str:
    MAX_CHARS = 257
    buffer = ctypes.create_unicode_buffer(MAX_CHARS)
    user32.GetWindowTextW(hwnd, buffer, MAX_CHARS)
    return buffer.value


def get_browser_hwnd(product_name: str, pid: int) -> HWND:
    found: List[HWND] = []

    @ctypes.WINFUNCTYPE(BOOL, HWND, LPARAM)  # type: ignore[attr-defined, misc]
    def check_pid(hwnd: HWND, lParam: LPARAM) -> bool:  # noqa: N803
        window_pid = DWORD()
        user32.GetWindowThreadProcessId(hwnd, ctypes.byref(window_pid))
        if window_pid.value != pid:
            # EnumWindows should continue enumerating
            return True
        found.append(hwnd)
        # EnumWindows should stop enumerating (since we found the right window)
        return False

    @ctypes.WINFUNCTYPE(BOOL, HWND, LPARAM)  # type: ignore[attr-defined, misc]
    def check_window_name(hwnd: HWND, lParam: LPARAM) -> bool:  # noqa: N803
        window_name = name_from_hwnd(hwnd)
        if product_name not in window_name.lower():
            # EnumWindows should continue enumerating
            return True
        found.append(hwnd)
        # EnumWindows should stop enumerating (since we found the right window)
        return False

    if pid:
        user32.EnumWindows(check_pid, LPARAM(0))
    else:
        user32.EnumWindows(check_window_name, LPARAM(0))

    if not found:
        raise LookupError(f"Couldn't find {product_name} HWND")
    return found[0]


def to_ia2(node: IAccessiblePtr) -> IAccessible2Ptr:
    service = node.QueryInterface(IServiceProvider)
    return service.QueryService(IAccessible._iid_, IAccessible2_2)


def attributes_to_dict(attributes: Optional[str]) -> Dict[str, str]:
    """Parse an IAccessible2 attribute string ("name:value;name2:value2;")
    into a dict. The characters \\ : ; , = are backslash escaped."""
    result: Dict[str, str] = {}
    key: Optional[str] = None
    current = ""
    escaped = False
    for char in attributes or "":
        if escaped:
            current += char
            escaped = False
        elif char == "\\":
            escaped = True
        elif char == ":" and key is None:
            key = current
            current = ""
        elif char == ";":
            if key is not None:
                result[key] = current
            key = None
            current = ""
        else:
            current += char
    if key is not None:
        result[key] = current
    return result
